def own_time(label,function,*args):
    trials=[timed_call(label,function,*args) for _ in range(3)]
    return min(trials,key=lambda pair:pair[1])
import numpy as np

def fee_apply(r):
    if r["amount"] > 1500:
        return 0
    if r["items"] >= 4:
        return 60
    return 15 * r["items"]

def fee_col(d):
    return np.where(d["amount"] > 1500, 0,
                    np.where(d["items"] >= 4, 60, 15 * d["items"]))

a, t_apply = own_time("apply", lambda table: table.apply(fee_apply, axis=1), d)
b, t_col = own_time("col", fee_col, d)
speedup = t_apply / t_col if t_col > 0 else None
total = int(fee_col(d).sum())
print(f"apply {t_apply:.4f} с, столбцы {t_col:.5f} с, быстрее в {speedup} раз; сборов {total} ₽")

